      let sum = 0;
      for (let j = 0; j < FK; j++) if (famTop[o + j] > -Infinity) sum += Math.exp(famTop[o + j] - mx);
      const sc = mx + Math.log(sum) - (1 - FPRIOR) * famLogW[t];
