    get: (key) => st[key] || null,
    set: (key, map) => { st = { ...st, [key]: map }; emit(); },
    reset: (key) => { const n = { ...st }; delete n[key]; st = n; emit(); },
    subscribe: (fn) => (subs.add(fn), () => subs.delete(fn)),
