    key, avail: set.avail, on,
    toggle: (id) => fieldStore.set(key, { ...(saved || {}), [id]: !on(id) }),
    setAll: (v) => fieldStore.set(key, Object.fromEntries(set.avail.map((id) => [id, v]))),
